package com.smartexam.entity;
import com.baomidou.mybatisplus.annotation.*; import lombok.Data; import java.math.BigDecimal; import java.time.LocalDateTime;
@Data @TableName("ai_grading_results") public class AiGradingResults {
 @TableId(type=IdType.AUTO) private Long id; @TableField("answer_id") private Long answerId; @TableField(value="ai_score", updateStrategy=FieldStrategy.ALWAYS) private BigDecimal aiScore; @TableField(value="ai_reason", updateStrategy=FieldStrategy.ALWAYS) private String aiReason; @TableField(value="ai_comment", updateStrategy=FieldStrategy.ALWAYS) private String aiComment; @TableField(value="matched_points", updateStrategy=FieldStrategy.ALWAYS) private String matchedPoints; @TableField(value="missing_points", updateStrategy=FieldStrategy.ALWAYS) private String missingPoints; private String status; @TableField(value="error_message", updateStrategy=FieldStrategy.ALWAYS) private String errorMessage; @TableField("created_at") private LocalDateTime createdAt; @TableField("updated_at") private LocalDateTime updatedAt;
}
